package javiertorres.amazonconbackend22settembre.controller;
import javiertorres.amazonconbackend22settembre.dto.AuthDtos.UserResponse; import javiertorres.amazonconbackend22settembre.service.AuthService; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/utenti") @PreAuthorize("hasRole('ADMIN')") public class AdminUserController { private final AuthService service; public AdminUserController(AuthService s){this.service=s;} @PostMapping("/{id}/ruolo-admin") public UserResponse grantAdmin(@PathVariable UUID id){return service.grantAdmin(id);} @DeleteMapping("/{id}/ruolo-admin") public UserResponse revokeAdmin(@PathVariable UUID id){return service.revokeAdmin(id);} }
